function validate([maze, start, destination]) {
  if (!Array.isArray(maze) || maze.length < 1 || maze.length > 100) return 'maze needs 1 to 100 rows.';
  const cols = maze[0].length;
  if (cols < 1 || cols > 100) return 'maze needs 1 to 100 columns.';
  if (maze.some(row => row.length !== cols)) return 'Every row of maze must have the same length.';
  if (maze.some(row => row.some(v => v !== 0 && v !== 1))) return 'maze holds only 0 and 1.';
  for (const [name, cell] of [['start', start], ['destination', destination]]) {
    if (!Array.isArray(cell) || cell.length !== 2) return `${name} must be [row, col].`;
    const [r, c] = cell;
    if (!Number.isInteger(r) || !Number.isInteger(c) || r < 0 || r >= maze.length || c < 0 || c >= cols) return `${name} must lie inside the maze.`;
    if (maze[r][c] !== 0) return `${name} must be an open cell.`;
  }
  if (start[0] === destination[0] && start[1] === destination[1]) return 'start and destination must be different cells.';
  return null;
}

