function shortestDistance(maze, start, destination) {
  const rows = maze.length;
  const cols = maze[0].length;
  const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  const dist = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  dist[start[0]][start[1]] = 0;
  // Min-heap of [distance, row, col], ordered by distance.
  const heap = [[0, start[0], start[1]]];
  const push = (item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0 && heap[(i - 1) >> 1][0] > heap[i][0]) {
      [heap[i], heap[(i - 1) >> 1]] = [heap[(i - 1) >> 1], heap[i]];
      i = (i - 1) >> 1;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    let i = 0;
    while (heap.length > 0) {
      heap[i] = last;
      const left = 2 * i + 1;
      let smallest = i;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (left + 1 < heap.length && heap[left + 1][0] < heap[smallest][0]) smallest = left + 1;
      if (smallest === i) break;
      heap[i] = heap[smallest];
      i = smallest;
    }
    return top;
  };

  while (heap.length > 0) {
    const [d, row, col] = pop();
    if (d > dist[row][col]) continue;
    if (row === destination[0] && col === destination[1]) return d;
    for (const [dr, dc] of directions) {
      let r = row;
      let c = col;
      let steps = 0;
      while (r + dr >= 0 && r + dr < rows && c + dc >= 0 && c + dc < cols && maze[r + dr][c + dc] === 0) {
        r += dr;
        c += dc;
        steps++;
      }
      if (d + steps < dist[r][c]) {
        dist[r][c] = d + steps;
        push([dist[r][c], r, c]);
      }
    }
  }
  return -1;
}

