function shortestDistance(maze, start, destination) {
  // Bellman-Ford over stopping cells: relax every roll from every reached stop until nothing improves.
  const open = (r, c) => r >= 0 && r < maze.length && c >= 0 && c < maze[0].length && maze[r][c] === 0;
  const best = new Map([[start.join(','), 0]]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [key, d] of [...best]) {
      const [r0, c0] = key.split(',').map(Number);
      for (const [dr, dc] of [[0, 1], [1, 0], [0, -1], [-1, 0]]) {
        let r = r0, c = c0, len = 0;
        while (open(r + dr, c + dc)) { r += dr; c += dc; len++; }
        const next = r + ',' + c;
        if (!best.has(next) || best.get(next) > d + len) { best.set(next, d + len); changed = true; }
      }
    }
  }
  const key = destination.join(',');
  return best.has(key) ? best.get(key) : -1;
}

