function generate(rand, size) {
  const rows = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  let cols = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  if (rows * cols < 2) cols = 2;
  const density = rand() * 0.45;
  const sides = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  for (;;) {
    const maze = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < density ? 1 : 0)));
    const open = (r, c) => r >= 0 && r < rows && c >= 0 && c < cols && maze[r][c] === 0;
    const empty = [];
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) if (maze[r][c] === 0) empty.push([r, c]);
    if (empty.length < 2) continue;
    const start = empty[Math.floor(rand() * empty.length)];
    // Most of the time aim at a stop the ball can really reach, so many answers are not -1.
    const seen = new Set([start.join(',')]);
    const stack = [start];
    while (stack.length) {
      const [r0, c0] = stack.pop();
      for (const [dr, dc] of sides) {
        let r = r0, c = c0;
        while (open(r + dr, c + dc)) { r += dr; c += dc; }
        if (!seen.has(r + ',' + c)) { seen.add(r + ',' + c); stack.push([r, c]); }
      }
    }
    seen.delete(start.join(','));
    const reachable = [...seen].map(key => key.split(',').map(Number));
    const others = empty.filter(([r, c]) => r !== start[0] || c !== start[1]);
    const pool = reachable.length && rand() < 0.75 ? reachable : others;
    return [maze, start, pool[Math.floor(rand() * pool.length)]];
  }
}
